@dataclass
class VeloraConfig:
    """
    This is the sub-configuration class to store the configuration for VeLoRA (Memory Efficient Training using Rank-1
    Sub-Token Projections). VeLoRA was introduced in <a href='https://huggingface.co/papers/2405.17991'>VeLoRA: Memory
    Efficient Training using Rank-1 Sub-Token Projections</a>.

    VeLoRA reduces the peak GPU memory usage during LoRA fine-tuning by compressing the input activations that are kept
    around for the backward pass. Each token is split into `num_groups` sub-tokens which are projected onto a single
    direction, and the activations used for the weight gradient are approximately reconstructed from this compressed
    representation.

    Args:
        num_groups (`int`):
            Number of sub-token groups to split each token into before projecting onto the compression direction.
            Defaults to `64`.
        scale (`float`):
            Scaling factor applied to the reconstructed activations during the backward pass. Defaults to `1.0`.
        init_type (`str`):
            How to initialize the projection direction (`embed`). One of `'batch_average_once'` (compute from the first
            training batch and then freeze), `'batch_average'` (recompute from every training batch) or `'random'`
            (use a fixed normalized random direction). Defaults to `'batch_average'`.
    """

    num_groups: int = field(
        default=64,
        metadata={"help": "Number of sub-token groups to split each token into before compression."},
    )
    scale: float = field(
        default=1.0,
        metadata={"help": "Scaling factor applied to the reconstructed activations during the backward pass."},
    )
    init_type: str = field(
        default="batch_average",
        metadata={
            "help": (
                "How to initialize the projection direction. One of 'batch_average_once', 'batch_average', "
                "or 'random'."
            )
        },
    )

    def __post_init__(self):
        if self.num_groups <= 0:
            raise ValueError(f"`num_groups` should be positive, got {self.num_groups}.")
        if self.scale <= 0.0:
            raise ValueError(f"`scale` should be positive, got {self.scale}.")
        if self.init_type not in ("batch_average_once", "batch_average", "random"):
            raise ValueError(
                f"Unsupported `init_type` '{self.init_type}'. Supported values are 'batch_average_once', "
                "'batch_average', and 'random'."
            )


